#!/data/data/com.termux/files/usr/bin/bash
# apply_all41.sh - اللغة الإنجليزية للأولى ثانوي: الجزء 1 = 29 بطاقة + الخرائط الذهنية (زر 🗺️)
# لا يمسّ مفتاح الترخيص: يضيف ملفات جديدة ووسوم script فقط في index.html بعد نسخة احتياطية.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f index.html.bak_en1 ] || cp index.html index.html.bak_en1

# --- اكتشاف مفتاح مادة اللغة الإنجليزية في الأولى ثانوي (كل الشعب) من db.js ---
CH=$(tr -d '\n' < db.js | sed 's/"AS1": *{"name"/\n&/' | tail -1 | sed 's/"AS2": *{"name".*//')
KE=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"[^"]*\(الإنجليزية\|الانجليزية\|الإنكليزية\)[^"]*"' | sed 's/"key": *"\([^"]*\)".*/\1/' | sort -u)
if [ -z "$KE" ]; then
  printf '%s' "$CH" | head -c 4000 > ~/storage/downloads/en1_diag.txt
  echo "لم أجد مادة اللغة الإنجليزية للأولى ثانوي في db.js. كتبتُ تشخيصا في التنزيلات: en1_diag.txt - أرسله لي."
  echo "لم يُغيَّر شيء."
  exit 1
fi
JE=$(printf '%s\n' $KE | sed 's/.*/"&"/' | paste -sd, | sed 's/^/[/;s/$/]/')
echo "مفاتيح اللغة الإنجليزية: $JE"

cat > en1_data.js <<'ZAD_EOF'
